import { Component } from '@angular/core';

@Component({
  selector: 'app-not-found',
  templateUrl: './not-found.component.html',
  styleUrls: ['./not-found.component.css']
})
export class NotFoundComponent {
}
<div class="page">
<app-header variant="guest"></app-header>

<div class="err-wrap">
  <div class="err-code">404</div>
  <h2 style="margin-top:12px;font-size:24px;">This page went unlisted.</h2>
  <p class="muted" style="margin-top:10px;max-width:380px;">The job, company or page you're looking for isn't here anymore.</p>
  <a routerLink="/" class="btn btn-primary" style="margin-top:24px;">Back to home</a>
</div>

<app-footer></app-footer>
</div>
